//! Inkling-2-Mini tokenizer.json Split pattern, before its ByteLevel mapping.
//! The order of alternatives matters, especially for combining marks, which
//! can belong to a word, its optional prefix, or a punctuation run.

const UPPER: u8 = 1; // Lu or Lt
const LOWER: u8 = 2; // Ll
const UNCASED: u8 = 3; // Lm or Lo
const MARK: u8 = 4;
const NUMBER: u8 = 5;
const SPACE: u8 = 6;

fn class(c: char) -> u8 {
    // Generated by tools/generate_inkling_char_classes.py using the regex engine's
    // own Unicode properties. A page index for every 256 scalars precedes the data.
    let table = include_bytes!("classes.bin");
    let n = c as usize;
    let page = usize::from(table[n >> 8]);
    let byte = table[0x1100 + page * 128 + (n & 255) / 2];
    (byte >> ((n & 1) * 4)) & 15
}

fn upper_group(kind: u8) -> bool {
    matches!(kind, UPPER | UNCASED | MARK)
}

fn lower_group(kind: u8) -> bool {
    matches!(kind, LOWER | UNCASED | MARK)
}

// The first word alternative requires a nonempty lower group after a greedy
// upper group. If that fails, it backtracks to the last shared character.
// The second alternative permits an empty lower group but requires an upper.
fn word_len(s: &str, require_lower: bool) -> Option<usize> {
    let mut end = 0;
    let mut last_shared = None;
    for (i, c) in s.char_indices() {
        let k = class(c);
        if !upper_group(k) {
            break;
        }
        end = i + c.len_utf8();
        if lower_group(k) {
            last_shared = Some(end);
        }
    }
    if !require_lower && end == 0 {
        return None;
    }
    let upper_end = end;
    for c in s[upper_end..]
        .chars()
        .take_while(|&c| lower_group(class(c)))
    {
        end += c.len_utf8();
    }
    if require_lower && end == upper_end {
        last_shared
    } else {
        Some(end)
    }
}

fn contraction_len(s: &str) -> usize {
    let Some(tail) = s.strip_prefix('\'') else {
        return 0;
    };
    for suffix in ["s", "t", "re", "ve", "m", "ll", "d"] {
        if tail
            .get(..suffix.len())
            .is_some_and(|v| v.eq_ignore_ascii_case(suffix))
        {
            return 1 + suffix.len();
        }
    }
    // Unicode simple case folding also equates long s with ASCII s.
    if tail.starts_with('ſ') {
        1 + 'ſ'.len_utf8()
    } else {
        0
    }
}

fn is_newline(c: char) -> bool {
    matches!(c, '\r' | '\n')
}

fn piece_len(text: &str, first: char) -> usize {
    let k = class(first);
    let prefix = if !is_newline(first) && !matches!(k, UPPER | LOWER | UNCASED | NUMBER) {
        first.len_utf8()
    } else {
        0
    };
    for require_lower in [true, false] {
        if let Some(n) = word_len(&text[prefix..], require_lower) {
            let end = prefix + n;
            return end + contraction_len(&text[end..]);
        }
        if prefix > 0 && k == MARK {
            if let Some(end) = word_len(text, require_lower) {
                return end + contraction_len(&text[end..]);
            }
        }
    }
    if k == NUMBER {
        return text
            .chars()
            .take(3)
            .take_while(|&c| class(c) == NUMBER)
            .map(char::len_utf8)
            .sum();
    }
    let mut end = usize::from(first == ' ');
    let prefix_end = end;
    for c in text[end..]
        .chars()
        .take_while(|&c| matches!(class(c), 0 | MARK))
    {
        end += c.len_utf8();
    }
    if end > prefix_end {
        for c in text[end..]
            .chars()
            .take_while(|&c| is_newline(c) || c == '/')
        {
            end += c.len_utf8();
        }
        return end;
    }
    // The whitespace branches prefer a run through its last CR/LF. Otherwise
    // leave one space before non-whitespace if at least two were available.
    let mut end = 0;
    let mut before_last = 0;
    let mut last_newline = None;
    for c in text.chars().take_while(|&c| class(c) == SPACE) {
        before_last = end;
        end += c.len_utf8();
        if is_newline(c) {
            last_newline = Some(end);
        }
    }
    last_newline.unwrap_or(if end < text.len() && before_last != 0 {
        before_last
    } else {
        end
    })
}

pub(super) fn split(mut text: &str) -> impl Iterator<Item = &str> {
    std::iter::from_fn(move || {
        let first = text.chars().next()?;
        let (piece, rest) = text.split_at(piece_len(text, first));
        text = rest;
        Some(piece)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn checkpoint_piece_boundaries() {
        // From the first Split stage in the official tokenizer.json, before ByteLevel.
        for (text, expected) in [
            ("Hello NASA's I’ll", &["Hello", " NASA's", " I", "’ll"][..]),
            ("e\u{301}cole CAFÉ", &["e\u{301}cole", " CAFÉ"]),
            ("漢A", &["漢", "A"]),
            (" A漢Bz", &[" A漢Bz"]),
            (
                "    a\n\n  b\t  ",
                &["   ", " a", "\n\n", " ", " b", "\t  "],
            ),
            ("２٣4Ⅷ", &["２٣4", "Ⅷ"]),
            ("abc!!!///\n", &["abc", "!!!///\n"]),
            ("it's I'll've D'ſ", &["it's", " I'll", "'ve", " D'ſ"]),
            ("\u{301}AB", &["\u{301}", "AB"]),
            ("?!/\r\n//abc", &["?!/\r\n//", "abc"]),
            ("x\u{a0} y", &["x", "\u{a0}", " y"]),
            ("a\0b", &["a", "\0b"]),
            ("", &[]),
        ] {
            assert_eq!(split(text).collect::<Vec<_>>(), expected, "{text:?}");
        }
    }
}
